package ratelimiter

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiter.
// It allows a burst of requests up to the bucket capacity,
// and refills at a configurable rate.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64      // maximum number of tokens the bucket can hold
	tokens      float64      // current number of tokens in the bucket
	refillRate  float64      // tokens added per second
	lastRefill  time.Time    // last time tokens were refilled
}

// New creates a new RateLimiter with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func New(capacity int, refillRate float64) *RateLimiter {
	return &RateLimiter{
		capacity:   float64(capacity),
		tokens:     float64(capacity), // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow checks if a request is permitted right now.
// It returns true if a token is available, false otherwise.
// This method is safe for concurrent use.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()

	if rl.tokens >= 1.0 {
		rl.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on elapsed time.
// This method must be called with the mutex held.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.lastRefill = now

	// Add tokens based on elapsed time
	rl.tokens += elapsed * rl.refillRate

	// Cap tokens at capacity
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
}

// Tokens returns the current number of tokens in the bucket.
// This is useful for testing and monitoring.
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}

// Capacity returns the maximum capacity of the bucket.
func (rl *RateLimiter) Capacity() int {
	return int(rl.capacity)
}
