// Package tokenbucket implements a token-bucket rate limiter.
package tokenbucket

import (
	"sync"
	"time"
)

// Limiter implements a token-bucket rate limiter.
type Limiter struct {
	mu          sync.Mutex
	capacity    float64 // maximum number of tokens the bucket can hold
	tokens      float64 // current number of tokens in the bucket
	refillRate  float64 // tokens added per second
	lastRefill  time.Time // time of last refill
}

// New creates a new token-bucket limiter.
// capacity is the maximum number of tokens the bucket can hold.
// refillRate is the number of tokens added per second.
func New(capacity, refillRate float64) *Limiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refillRate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start full
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.lastRefill = now

	// Check if we have at least one token
	if l.tokens >= 1 {
		l.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of tokens available (for testing/debugging).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	// Refill first to get accurate count
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.lastRefill = now
	return l.tokens
}
