package ratelimit

import (
	"sync"
	"time"
)

// TokenBucket implements a token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type TokenBucket struct {
	mu          sync.Mutex
	capacity    float64       // maximum number of tokens the bucket can hold
	tokens      float64       // current number of tokens in the bucket
	refillRate  float64       // tokens added per second
	lastRefill  time.Time     // last time the bucket was refilled
}

// NewTokenBucket creates a new TokenBucket with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func NewTokenBucket(capacity float64, refillRate float64) *TokenBucket {
	now := time.Now()
	return &TokenBucket{
		capacity:   capacity,
		tokens:     capacity, // start full to allow initial burst
		refillRate: refillRate,
		lastRefill: now,
	}
}

// refill adds tokens based on the elapsed time since the last refill.
// The caller must hold the mutex.
func (tb *TokenBucket) refill() {
	now := time.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	if elapsed > 0 {
		tb.tokens += elapsed * tb.refillRate
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.lastRefill = now
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	tb.refill()

	if tb.tokens >= 1.0 {
		tb.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of tokens in the bucket (for testing/debugging).
func (tb *TokenBucket) Tokens() float64 {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	tb.refill()
	return tb.tokens
}
