```go
// Package tokenbucket provides a token-bucket rate limiter implementation.
package tokenbucket

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiting algorithm.
// It allows a configurable burst capacity and a steady refill rate.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64
	tokens      float64
	refillRate  float64 // tokens per second
	lastRefill  time.Time
}

// New creates a new RateLimiter with the given capacity (maximum burst)
// and refillRate (tokens added per second).
// Both parameters must be positive.
func New(capacity, refillRate float64) *RateLimiter {
	if capacity <= 0 || refillRate <= 0 {
		panic("tokenbucket: capacity and refillRate must be positive")
	}
	return &RateLimiter{
		capacity:   capacity,
		tokens:     capacity, // start full
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted at the current moment.
// It consumes one token if available, otherwise returns false.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	// Refill tokens based on elapsed time
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.tokens += elapsed * rl.refillRate
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
	rl.lastRefill = now

	// Check if we have at least one token
	if rl.tokens >= 1 {
		rl.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for debugging/testing).
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	// Apply refill before returning
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.tokens += elapsed * rl.refillRate
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
	rl.lastRefill = now
	return rl.tokens
}
