// Package ratelimit implements a token-bucket rate limiter.
package ratelimit

import (
	"sync"
	"time"
)

// Limiter implements a token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu          sync.Mutex
	capacity    float64
	tokens      float64
	refillRate  float64 // tokens per second
	lastRefill  time.Time
}

// New creates a new Limiter with the given capacity (maximum burst size)
// and refillRate (tokens added per second).
// Both capacity and refillRate must be positive.
func New(capacity, refillRate float64) *Limiter {
	if capacity <= 0 {
		panic("ratelimit: capacity must be positive")
	}
	if refillRate <= 0 {
		panic("ratelimit: refillRate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start full
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted at the current moment.
// It consumes one token if allowed, and returns false if no tokens are available.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now

	// Add tokens based on elapsed time, capped at capacity
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}

	// Check if we have at least one token
	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for debugging/testing).
// This method is not part of the core API but useful for tests.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill first to get accurate count
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	return l.tokens
}
