 * @param {string} password - The password to validate
 * @returns {Object} - { isValid: boolean, error: string|null, strength: string }
 */
function validatePasswordStrength(password) {
  // Edge case: empty or non-string input
  if (typeof password !== 'string' || password.length === 0) {
    return { isValid: false, error: 'Password is required', strength: 'none' };
  }

  // Edge case: password too short
  if (password.length < 8) {
    return { 
      isValid: false, 
      error: 'Password must be at least 8 characters long', 
      strength: 'weak' 
    };
  }

  // Check for various character types
  const hasUpperCase = /[A-Z]/.test(password);
  const hasLowerCase = /[a-z]/.test(password);
  const hasNumbers = /\d/.test(password);
  const hasSpecialChars = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);

  // Count how many character types are present
  const typeCount = [hasUpperCase, hasLowerCase, hasNumbers, hasSpecialChars].filter(Boolean).length;

  // Determine password strength
  let strength = 'weak';
  if (typeCount >= 3 && password.length >= 10) {
    strength = 'strong';
  } else if (typeCount >= 2 && password.length >= 8) {
    strength = 'medium';
  }

  // Validation rules
  if (typeCount < 2) {
    return { 
      isValid: false, 
      error: 'Password must contain at least two of: uppercase letters, lowercase letters, numbers, special characters', 
      strength 
    };
  }

  // Edge case: password with only one type of character
  if (typeCount === 1) {
    return { 
      isValid: false, 
      error: 'Password is too weak - needs more variety of characters', 
      strength: 'weak' 
    };
  }

  // Edge case: password with spaces
  if (/\s/.test(password)) {
    return { 
      isValid: false, 
      error: 'Password cannot contain spaces', 
      strength 
    };
  }

  return { isValid: true, error: null, strength };
}

