  if (password.length < 8) {
    return { isValid: false, error: 'Password must be at least 8 characters long' };
  }

  // Check for uppercase letter
  if (!/[A-Z]/.test(password)) {
    return { isValid: false, error: 'Password must contain at least one uppercase letter' };
  }

  // Check for lowercase letter
  if (!/[a-z]/.test(password)) {
    return { isValid: false, error: 'Password must contain at least one lowercase letter' };
  }

  // Check for number
  if (!/\d/.test(password)) {
    return { isValid: false, error: 'Password must contain at least one number' };
  }

  // Check for special character
  if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
    return { isValid: false, error: 'Password must contain at least one special character' };
  }

  // Edge case: check for common weak passwords
  const commonPasswords = ['password', '12345678', 'qwerty123', 'admin123'];
  if (commonPasswords.includes(password.toLowerCase())) {
    return { isValid: false, error: 'Password is too common and easily guessable' };
  }

  return { isValid: true, error: null };
}

/**
 * Validates username
 * @param {string} username - The username to validate
 * @returns {Object} - { isValid: boolean, error: string|null }
 */
function validateUsername(username) {
  // Edge case: empty or non-string input
  if (!username || typeof username !== 'string') {
    return { isValid: false, error: 'Username is required' };
  }

  // Trim whitespace
  username = username.trim();

  // Check length (3-20 characters)
  if (username.length < 3 || username.length > 20) {
    return { isValid: false, error: 'Username must be between 3 and 20 characters' };
  }

  // Check allowed characters (letters, numbers, underscore, hyphen)
  const usernameRegex = /^[a-zA-Z0-9_-]+$/;
  if (!usernameRegex.test(username)) {
    return { isValid: false, error: 'Username can only contain letters, numbers, underscores, and hyphens' };
  }

  // Edge case: check if username starts with a number
  if (/^[0-9]/.test(username)) {
    return { isValid: false, error: 'Username cannot start with a number' };
  }

  // Edge case: check for consecutive underscores or hyphens
  if (username.includes('__') || username.includes('--')) {
    return { isValid: false, error: 'Username cannot contain consecutive underscores or hyphens' };
  }

  return { isValid: true, error: null };
}

/**
 * Validates complete registration form
 * @param {Object} formData - { email: string, password: string, username: string }
 * @returns {Object} - { isValid: boolean, fields: { email: {isValid, error}, password: {isValid, error}, username: {isValid, error} } }
 */
function validateRegistration(formData) {
  // Edge case: handle missing or malformed formData
  if (!formData || typeof formData !== 'object') {
    return {
      isValid: false,
      fields: {
        email: { isValid: false, error: 'Email is required' },
        password: { isValid: false, error: 'Password is required' },
