// Package ratelimit implements a token-bucket rate limiter.
package ratelimit

import (
	"sync"
	"time"
)

// Limiter represents a token-bucket rate limiter.
type Limiter struct {
	mu sync.Mutex

	capacity float64 // maximum number of tokens the bucket can hold
	tokens   float64 // current number of tokens in the bucket

	refillRate float64 // tokens added per second
	lastRefill time.Time // last time tokens were refilled
}

// NewLimiter creates a new rate limiter with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func NewLimiter(capacity float64, refillRate float64) *Limiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refillRate must be positive")
	}

	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill()

	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since last refill.
// Must be called with the mutex held.
func (l *Limiter) refill() {
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed <= 0 {
		return
	}

	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.lastRefill = now
}

// Tokens returns the current number of tokens (for testing/debugging).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}
