type Limiter struct {
	mu        sync.Mutex
	capacity  float64
	tokens    float64
	refillRate float64 // tokens per second
	lastRefill time.Time
}

// New creates a new Limiter with the given capacity and refill rate.
// capacity is the maximum number of tokens that can be accumulated (burst size).
// refillRate is the number of tokens added per second.
func New(capacity int, refillRate float64) *Limiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refill rate must be positive")
	}
	now := time.Now()
	return &Limiter{
		capacity:   float64(capacity),
		tokens:     float64(capacity), // start full
		refillRate: refillRate,
		lastRefill: now,
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	l.refill()

	// Check if we have at least one token
	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// refill adds tokens based on time elapsed since last refill.
// Must be called with the mutex held.
func (l *Limiter) refill() {
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.refillRate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.lastRefill = now
	}
}

// Tokens returns the current number of tokens (for debugging/testing).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
