// NewLimiter creates a new rate limiter with the given capacity (max burst)
// and refill rate (tokens per second).
// Both capacity and rate must be positive.
func NewLimiter(capacity, rate float64) *Limiter {
	if capacity <= 0 || rate <= 0 {
		panic("ratelimit: capacity and rate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start full to allow immediate burst
		rate:       rate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted at the current moment.
// It consumes one token if available, otherwise returns false.
// The method is safe for concurrent use.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now

	// Add tokens proportional to elapsed time, capped at capacity
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}

	// Check if we have at least one token
	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of tokens available (for testing/debugging).
// This method is safe for concurrent use.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill first to get accurate count
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	return l.tokens
}
