// Package ratelimit implements a token-bucket rate limiter.
package ratelimit

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiting algorithm.
// It allows a configurable burst capacity and refill rate.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64      // maximum number of tokens the bucket can hold
	tokens      float64      // current number of tokens in the bucket
	refillRate  float64      // tokens added per second
	lastRefill  time.Time    // last time the bucket was refilled
}

// New creates a new RateLimiter with the given capacity and refill rate.
// capacity: maximum burst size (number of tokens the bucket can hold)
// refillRate: number of tokens added per second
func New(capacity, refillRate float64) *RateLimiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refillRate must be positive")
	}
	return &RateLimiter{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow checks if a request is permitted right now.
// It consumes one token if available and returns true,
// otherwise returns false without consuming anything.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()

	if rl.tokens >= 1 {
		rl.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on elapsed time since last refill.
// Must be called with the mutex held.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.tokens += elapsed * rl.refillRate
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
	rl.lastRefill = now
}

// Tokens returns the current number of tokens in the bucket (for testing/debugging).
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}
