// TestBurstAllowance verifies that up to capacity requests are allowed immediately.
func TestBurstAllowance(t *testing.T) {
	capacity := 5.0
	refillRate := 1.0 // 1 token per second
	limiter := NewLimiter(capacity, refillRate)

	// Should allow exactly capacity requests
	for i := 0; i < int(capacity); i++ {
		if !limiter.Allow() {
			t.Fatalf("request %d should be allowed (burst)", i+1)
		}
	}

	// Next request should be denied (bucket empty)
	if limiter.Allow() {
		t.Fatal("request beyond capacity should be denied")
	}
}

// TestRefillBehavior verifies that tokens are refilled over time.
func TestRefillBehavior(t *testing.T) {
	capacity := 3.0
	refillRate := 2.0 // 2 tokens per second
	limiter := NewLimiter(capacity, refillRate)

	// Drain the bucket
	for i := 0; i < int(capacity); i++ {
		if !limiter.Allow() {
			t.Fatalf("initial request %d should be allowed", i+1)
		}
	}

	// Verify bucket is empty
	if limiter.Allow() {
		t.Fatal("bucket should be empty after draining")
	}

	// Wait for 1 second → should have 2 tokens refilled
	time.Sleep(1 * time.Second)

	// Should allow 2 requests
	for i := 0; i < 2; i++ {
		if !limiter.Allow() {
			t.Fatalf("request %d after 1s should be allowed", i+1)
		}
	}

	// Third request should be denied (only 2 tokens refilled)
	if limiter.Allow() {
		t.Fatal("request beyond refilled tokens should be denied")
	}

	// Wait for 0.5 seconds → should have 1 more token (2 * 0.5 = 1)
	time.Sleep(500 * time.Millisecond)

	if !limiter.Allow() {
		t.Fatal("request after additional 0.5s should be allowed")
	}

	// Bucket should be empty again
	if limiter.Allow() {
		t.Fatal("bucket should be empty after consuming refilled token")
	}
}

