	// Drain the bucket
	limiter.Allow()
	limiter.Allow()

	// Wait long enough to refill well beyond capacity
	time.Sleep(2 * time.Second)

	// Should only have capacity tokens available
	allowed := 0
	for i := 0; i < int(capacity); i++ {
		if limiter.Allow() {
			allowed++
		}
	}

	if allowed != int(capacity) {
		t.Fatalf("expected %d allowed requests, got %d", int(capacity), allowed)
	}

	// Next should be denied
	if limiter.Allow() {
		t.Fatal("should not exceed capacity even after long wait")
	}
