// Package ratelimit implements a token-bucket rate limiter.
package ratelimit

import (
	"sync"
	"time"
)

// Limiter implements a token-bucket rate limiter.
// It allows a configurable burst capacity and refill rate.
// The zero value is not usable; use NewLimiter to create one.
type Limiter struct {
	mu       sync.Mutex
	capacity float64 // maximum number of tokens the bucket can hold
	tokens   float64 // current number of tokens in the bucket
	rate     float64 // tokens added per second
	lastRefill time.Time // last time tokens were refilled
}

// NewLimiter creates a new rate limiter with the given capacity (max burst)
// and refill rate (tokens per second).
// Both capacity and rate must be positive.
func NewLimiter(capacity, rate float64) *Limiter {
	if capacity <= 0 || rate <= 0 {
		panic("ratelimit: capacity and rate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start full to allow immediate burst
		rate:       rate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted at the current moment.
// It consumes one token if available, otherwise returns false.
// The method is safe for concurrent use.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	now := time.Now()
