// Package ratelimit provides a token-bucket rate limiter implementation.
package ratelimit

import (
	"sync"
	"time"
)

// TokenBucket implements a token bucket rate limiter.
// It allows a configurable burst capacity and refill rate.
type TokenBucket struct {
	mu          sync.Mutex
	capacity    float64
	refillRate  float64 // tokens per second
	tokens      float64
	lastRefill  time.Time
}

// NewTokenBucket creates a new token bucket with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func NewTokenBucket(capacity float64, refillRate float64) *TokenBucket {
	if capacity <= 0 || refillRate <= 0 {
		panic("capacity and refillRate must be positive")
	}
	return &TokenBucket{
		capacity:   capacity,
		refillRate: refillRate,
		tokens:     capacity, // start full
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	// Refill tokens based on elapsed time
	tb.refill()

	if tb.tokens >= 1 {
		tb.tokens--
		return true
	}
	return false
}

// refill adds tokens based on the time elapsed since the last refill.
// Must be called with the mutex held.
func (tb *TokenBucket) refill() {
	now := time.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	if elapsed > 0 {
		tb.tokens += elapsed * tb.refillRate
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.lastRefill = now
	}
}

// Tokens returns the current number of tokens in the bucket (for testing/debugging).
func (tb *TokenBucket) Tokens() float64 {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	tb.refill()
	return tb.tokens
}
