// Package ratelimiter implements a token-bucket rate limiter.
package ratelimiter

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiting algorithm.
// It allows a configurable burst capacity and refill rate.
type RateLimiter struct {
	mu sync.Mutex

	capacity   float64 // maximum number of tokens the bucket can hold
	refillRate float64 // tokens added per second

	tokens     float64   // current number of tokens in the bucket
	lastRefill time.Time // last time tokens were refilled
}

// New creates a new RateLimiter with the given capacity and refill rate.
//
// Parameters:
//   - capacity: maximum number of tokens the bucket can hold (burst size)
//   - refillRate: number of tokens added per second
//
// Returns an error if either parameter is non-positive.
func New(capacity, refillRate float64) (*RateLimiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if refillRate <= 0 {
		return nil, ErrInvalidRefillRate
	}

	return &RateLimiter{
		capacity:   capacity,
		refillRate: refillRate,
		tokens:     capacity, // start with a full bucket
		lastRefill: time.Now(),
	}, nil
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()

	if rl.tokens >= 1 {
		rl.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on elapsed time since last refill.
// The caller must hold the mutex.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.lastRefill = now

	// Add tokens based on elapsed time, capped at capacity
	rl.tokens += elapsed * rl.refillRate
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
}

// Tokens returns the current number of tokens in the bucket.
// This is primarily for testing and debugging purposes.
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}

// Capacity returns the configured bucket capacity.
func (rl *RateLimiter) Capacity() float64 {
	return rl.capacity
}

// RefillRate returns the configured refill rate (tokens per second).
func (rl *RateLimiter) RefillRate() float64 {
	return rl.refillRate
}

// Errors returned by the New function
var (
	ErrInvalidCapacity  = &RateLimiterError{"invalid capacity: must be positive"}
	ErrInvalidRefillRate = &RateLimiterError{"invalid refill rate: must be positive"}
)

// RateLimiterError represents an error in rate limiter configuration.
type RateLimiterError struct {
	msg string
}

func (e *RateLimiterError) Error() string {
	return e.msg
}
