// This is primarily for testing and debugging purposes.
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}

// Capacity returns the configured bucket capacity.
func (rl *RateLimiter) Capacity() float64 {
	return rl.capacity
}

// RefillRate returns the configured refill rate (tokens per second).
func (rl *RateLimiter) RefillRate() float64 {
	return rl.refillRate
}

